class DuplicateJsonKeyError(ValueError):
    """Raised when a public JSON root contains a duplicate object key."""

    def __init__(self, key: str) -> None:
        super().__init__(key)
        self.key = key


def _reject_duplicate_json_keys(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    payload: dict[str, Any] = {}
    for key, value in pairs:
        if key in payload:
            raise DuplicateJsonKeyError(key)
        payload[key] = value
    return payload


def _load_json(path: Path) -> Any:
    return json.loads(
        path.read_text(encoding="utf-8"),
        object_pairs_hook=_reject_duplicate_json_keys,
    )


def _path_control_character(path: str) -> str | None:
    for character in path:
        if ord(character) < 0x20 or ord(character) == 0x7F:
            return repr(character)
    return None


MARKDOWN_UNSAFE_PATH_CHARACTERS = frozenset("|`<>")


def _path_markdown_unsafe_character(path: str) -> str | None:
    for character in path:
        if character in MARKDOWN_UNSAFE_PATH_CHARACTERS:
            return repr(character)
    return None


def _path_percent_encoded_traversal(path: str) -> str | None:
    decoded = path
    seen = {decoded}
    for _ in range(32):
        if "%" not in decoded:
            return None
        decoded = unquote(decoded)
        if decoded in seen:
            return None
        seen.add(decoded)
        decoded_path = PurePosixPath(decoded)
        if (
            decoded_path.is_absolute()
            or ".." in decoded_path.parts
            or "\\" in decoded
            or decoded != decoded_path.as_posix()
        ):
            return repr(path)
    if "%" in decoded:
        return repr(path)
    return None


def _canonical_json_text(payload: Any) -> str:
    return json.dumps(payload, indent=2, sort_keys=True) + "\n"


def _canonical_json_file_errors(label: str, path: Path, payload: Any) -> list[str]:
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return [f"cannot load {label} JSON for canonical serialization check"]
    if text != _canonical_json_text(payload):
        return [f"{label} JSON is not canonical release-bundle serialization"]
    return []


def _sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _artifact(path: Path) -> dict[str, Any]:
    if path.is_symlink():
        raise ValueError("release artifact path must not be a symlink")
    artifact_path = str(path)
    if artifact_path.strip() != artifact_path:
        raise ValueError("release artifact path must not contain surrounding whitespace")
    control_character = _path_control_character(artifact_path)
    if control_character is not None:
        raise ValueError(
            "release artifact path contains control character "
            f"{control_character}"
        )
    markdown_unsafe_character = _path_markdown_unsafe_character(artifact_path)
    if markdown_unsafe_character is not None:
        raise ValueError(
            "release artifact path contains Markdown-unsafe character "
            f"{markdown_unsafe_character}"
        )
    percent_traversal = _path_percent_encoded_traversal(artifact_path)
    if percent_traversal is not None:
        raise ValueError(
            "release artifact path contains percent-encoded traversal segment"
        )
    payload = path.read_bytes()
    return {
        "path": artifact_path,
        "bytes": len(payload),
        "sha256": hashlib.sha256(payload).hexdigest(),
    }


def _is_canonical_sha256_text(value: Any) -> bool:
    return (
        isinstance(value, str)
        and len(value) == 64
        and all(symbol in "0123456789abcdef" for symbol in value)
    )


def _native_evm_prover_artifact_metadata_blockers(
    artifact: Any,
    label: str,
) -> list[str]:
    prefix = f"native EVM Groth16 prover bundle {label}"
    if not isinstance(artifact, dict):
        return [f"{prefix} artifact metadata must be an object"]

    blockers: list[str] = []
    artifact_path = artifact.get("path")
    if (
        not isinstance(artifact_path, str)
        or not artifact_path
        or artifact_path.strip() != artifact_path
        or _path_control_character(artifact_path) is not None
        or _path_markdown_unsafe_character(artifact_path) is not None
        or _path_percent_encoded_traversal(artifact_path) is not None
    ):
        blockers.append(f"{prefix} artifact path metadata is invalid")

    artifact_bytes = artifact.get("bytes")
    if type(artifact_bytes) is not int or artifact_bytes < 0:
        blockers.append(f"{prefix} artifact bytes metadata is invalid")

    if not _is_canonical_sha256_text(artifact.get("sha256")):
        blockers.append(f"{prefix} artifact sha256 metadata is invalid")

    return blockers


def _load_module(name: str, path: Path) -> Any:
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"cannot load {path}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def _all_lanes_module() -> Any:
    return _load_module("_sccp_all_lanes_evidence", ALL_LANES_SCRIPT)


def _canonical_artifact_path(artifact: dict[str, Any]) -> tuple[str | None, list[str]]:
    artifact_path = artifact.get("path")
    if not isinstance(artifact_path, str) or not artifact_path:
        return None, ["manifest artifact has no path"]
    if artifact_path.strip() != artifact_path:
        return None, ["manifest artifact path must not contain surrounding whitespace"]
    control_character = _path_control_character(artifact_path)
    if control_character is not None:
        return None, [
            "manifest artifact path contains control character "
            f"{control_character}"
        ]
    markdown_unsafe_character = _path_markdown_unsafe_character(artifact_path)
    if markdown_unsafe_character is not None:
        return None, [
            "manifest artifact path contains Markdown-unsafe character "
            f"{markdown_unsafe_character}"
        ]
    percent_traversal = _path_percent_encoded_traversal(artifact_path)
    if percent_traversal is not None:
        return None, ["manifest artifact path contains percent-encoded traversal segment"]
    if "\\" in artifact_path:
        return None, ["manifest artifact path is not canonical"]
    path = PurePosixPath(artifact_path)
    if path.is_absolute() or ".." in path.parts:
        return None, ["manifest artifact path escapes bundle"]
    if artifact_path != path.as_posix():
        return None, ["manifest artifact path is not canonical"]
    return artifact_path, []


def _canonical_report_input_path_errors(value: Any) -> list[str]:
    if not isinstance(value, str) or not value:
        return ["readiness report inputs item must be a non-empty string"]
    if value.strip() != value:
        return [
            "readiness report inputs path must not contain surrounding whitespace"
        ]
    control_character = _path_control_character(value)
    if control_character is not None:
        return [
            "readiness report inputs path contains control character "
            f"{control_character}"
        ]
    markdown_unsafe_character = _path_markdown_unsafe_character(value)
    if markdown_unsafe_character is not None:
        return [
            "readiness report inputs path contains Markdown-unsafe character "
            f"{markdown_unsafe_character}"
        ]
    percent_traversal = _path_percent_encoded_traversal(value)
    if percent_traversal is not None:
        return [
            "readiness report inputs path contains percent-encoded traversal segment"
        ]
    if "\\" in value:
        return ["readiness report inputs path is not canonical"]
    path = PurePosixPath(value)
    if path.is_absolute() or ".." in path.parts:
        return ["readiness report inputs path escapes bundle"]
    if value != path.as_posix():
        return ["readiness report inputs path is not canonical"]
    return []


def _canonical_report_artifact_path_errors(label: str, value: str) -> list[str]:
    if value.strip() != value:
        return [
            f"{label} artifact path must not contain surrounding whitespace"
        ]
    control_character = _path_control_character(value)
    if control_character is not None:
        return [
            f"{label} artifact path contains control character "
            f"{control_character}"
        ]
    markdown_unsafe_character = _path_markdown_unsafe_character(value)
    if markdown_unsafe_character is not None:
        return [
            f"{label} artifact path contains Markdown-unsafe character "
            f"{markdown_unsafe_character}"
        ]
    percent_traversal = _path_percent_encoded_traversal(value)
    if percent_traversal is not None:
        return [f"{label} artifact path contains percent-encoded traversal segment"]
    if "\\" in value:
        return [f"{label} artifact path is not canonical"]
    path = PurePosixPath(value)
    if path.is_absolute() or ".." in path.parts:
        return [f"{label} artifact path escapes bundle"]
    if value != path.as_posix():
        return [f"{label} artifact path is not canonical"]
    return []


def _copied_input_layout_errors(label: str, index: int, value: Any) -> list[str]:
    if not isinstance(value, str) or _canonical_report_input_path_errors(value):
        return []
    expected_prefix = f"{index:02d}-"
    path = PurePosixPath(value)
    if (
        len(path.parts) != 2
        or path.parts[0] != "evidence"
        or not path.name.startswith(expected_prefix)
        or path.name == expected_prefix
        or not path.name.endswith(".toml")
    ):
        return [
            f"{label} path must use copied evidence layout "
            f"evidence/{expected_prefix}*.toml"
        ]
    return []


def _expected_phase_artifact_path(phase: str) -> str:
    return f"corridor/{phase}.log"


def _artifact_errors(bundle_dir: Path, artifact: dict[str, Any]) -> list[str]:
    errors: list[str] = []
    artifact_path, path_errors = _canonical_artifact_path(artifact)
    for key in sorted(set(artifact) - ARTIFACT_KEYS, key=str):
        if artifact_path is None:
            errors.append(
                _native_evm_prover_field_name_blocker(
                    "manifest artifact",
                    key,
                    "unknown",
                )
            )
        else:
            errors.append(
                _native_evm_prover_field_name_blocker(
                    "manifest artifact",
                    key,
                    "unknown",
                )
            )
    if path_errors:
        return [*errors, *path_errors]
    assert artifact_path is not None
    if artifact_path == MANIFEST_ROOT_PATH:
        return [
            *errors,
            f"manifest must not list verifier root as an artifact: {artifact_path}",
        ]
    path = bundle_dir.joinpath(*PurePosixPath(artifact_path).parts)
    current = bundle_dir
    for part in PurePosixPath(artifact_path).parts:
        current = current / part
        if current.is_symlink():
            return ["bundle artifact path uses symlink"]
    if not path.is_file():
        return ["missing bundle artifact"]
    expected_bytes = artifact.get("bytes")
    expected_hash = artifact.get("sha256")
    actual_bytes = path.stat().st_size
    actual_hash = _sha256(path)
    if type(expected_bytes) is not int or expected_bytes <= 0:
        errors.append("manifest artifact bytes must be a positive integer")
    elif expected_bytes != actual_bytes:
        errors.append(
            f"manifest artifact byte length mismatch: expected {expected_bytes}, got {actual_bytes}"
        )
    if not _is_canonical_sha256_text(expected_hash):
        errors.append(
            "manifest artifact sha256 must be a canonical SHA-256 hex string"
        )
    elif expected_hash != actual_hash:
        errors.append(
            f"manifest artifact sha256 mismatch: expected {expected_hash}, got {actual_hash}"
        )
    return errors


def _manifest_artifacts_by_path(
    artifacts: list[Any],
    errors: list[str],
) -> dict[str, dict[str, Any]]:
    by_path: dict[str, dict[str, Any]] = {}
    artifact_values = artifacts if isinstance(artifacts, list) else [None]
    for artifact in artifact_values:
        if not isinstance(artifact, dict):
            continue
        artifact_path, path_errors = _canonical_artifact_path(artifact)
        if path_errors or artifact_path is None:
            continue
        if artifact_path == MANIFEST_ROOT_PATH:
            continue
        if artifact_path in by_path:
            errors.append("duplicate manifest artifact path")
            continue
        by_path[artifact_path] = artifact
    return by_path


def _bundle_entry_paths(bundle_dir: Path, errors: list[str]) -> tuple[set[str], set[str]]:
    files: set[str] = set()
    directories: set[str] = set()
    try:
        candidates = sorted(bundle_dir.rglob("*"))
    except OSError:
        errors.append("cannot enumerate bundle files")
        return files, directories
    for candidate in candidates:
        try:
            relative = candidate.relative_to(bundle_dir).as_posix()
        except ValueError:
            errors.append("bundle file escapes bundle root")
            continue
        if candidate.is_symlink():
            errors.append("bundle contains symlink")
            continue
        control_character = _path_control_character(relative)
        if control_character is not None:
            errors.append(
                "bundle contains entry path with control character "
                f"{control_character}"
            )
            continue
        markdown_unsafe_character = _path_markdown_unsafe_character(relative)
        if markdown_unsafe_character is not None:
            errors.append(
                "bundle contains entry path with Markdown-unsafe character "
                f"{markdown_unsafe_character}"
            )
            continue
        relative_path = PurePosixPath(relative)
        if (
            "\\" in relative
            or relative_path.is_absolute()
            or ".." in relative_path.parts
        ):
            errors.append("bundle contains non-canonical entry path")
            continue
        if candidate.is_file():
            files.add(relative)
        elif candidate.is_dir():
            directories.add(relative)
        else:
            errors.append("bundle contains unsupported filesystem entry")
    return files, directories


def _expected_bundle_directories(expected_paths: set[str]) -> set[str]:
    directories: set[str] = set()
    for expected_path in expected_paths:
        path = PurePosixPath(expected_path)
        parent = path.parent
        while parent != PurePosixPath("."):
            directories.add(parent.as_posix())
            parent = parent.parent
    return directories


def _check_report_artifact(
    errors: list[str],
    manifest_artifacts: dict[str, dict[str, Any]],
    artifact: Any,
    *,
    label: str,
) -> None:
    if not isinstance(artifact, dict):
        errors.append(f"{label} artifact is not an object")
        return
    artifact_path = artifact.get("path")
    if not isinstance(artifact_path, str) or not artifact_path:
        errors.append(f"{label} artifact has no path")
        return
    for key in sorted(set(artifact) - ARTIFACT_KEYS, key=str):
        errors.append(
            _native_evm_prover_field_name_blocker(
                f"{label} artifact",
                key,
                "unknown",
            )
        )
    expected_bytes = artifact.get("bytes")
    if type(expected_bytes) is not int or expected_bytes <= 0:
        errors.append(f"{label} artifact bytes must be a positive integer")
    expected_hash = artifact.get("sha256")
    if not _is_canonical_sha256_text(expected_hash):
        errors.append(
            f"{label} artifact sha256 must be a canonical SHA-256 hex string"
        )
    path_errors = _canonical_report_artifact_path_errors(label, artifact_path)
    if path_errors:
        errors.extend(path_errors)
        return
    manifest_artifact = manifest_artifacts.get(artifact_path)
    if manifest_artifact is None:
        errors.append(f"{label} artifact is missing from manifest")
        return
    for field in ("bytes", "sha256"):
        if manifest_artifact.get(field) != artifact.get(field):
            errors.append(
                f"{label} artifact {field} mismatch: "
                f"manifest={manifest_artifact.get(field)!r}, "
                f"report={artifact.get(field)!r}"
            )


def _phase_transcript_errors(
    bundle_dir: Path,
    phase: str,
    artifact: Any,
) -> list[str]:
    path, artifact_path_errors = _phase_transcript_artifact_path(bundle_dir, artifact)
    if artifact_path_errors:
        return artifact_path_errors
    assert path is not None
    try:
        transcript = path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        return [f"readiness report phase {phase} evidence artifact is not UTF-8 text"]
    except OSError:
        return [f"readiness report phase {phase} evidence artifact cannot be read"]
    phase_block = _phase_transcript_block(phase, transcript)
    errors: list[str] = []
    if CORRIDOR_DRY_RUN_SENTINEL in transcript:
        errors.append(
            f"readiness report phase {phase} evidence artifact is a dry-run transcript"
        )
    if _unknown_corridor_phase_marker_lines(transcript):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact contains unknown corridor phase marker"
        )
    if _transcript_has_nonempty_line_before_first_phase_marker(transcript):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact contains non-empty output before "
            "first phase marker"
        )
    if phase_block is None:
        errors.append(
            f"readiness report phase {phase} evidence artifact is missing the phase marker"
        )
    elif _phase_marker_count(phase, transcript) > 1:
        errors.append(
            f"readiness report phase {phase} evidence artifact has duplicate phase marker"
        )
    elif (
        not _phase_block_has_exact_output_line(
            phase_block, CORRIDOR_COMPLETION_SENTINEL
        )
        and not _transcript_has_full_corridor_completion(transcript)
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact is missing the phase-block completion sentinel"
        )
    elif (
        _phase_block_has_exact_output_line(phase_block, CORRIDOR_COMPLETION_SENTINEL)
        and not _phase_block_has_completion_after_required_evidence(
            phase, phase_block
        )
        and not _transcript_has_full_corridor_completion(transcript)
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact completion sentinel precedes required "
            "phase evidence"
        )
    if (
        phase_block is not None
        and _phase_block_has_traced_command_after_completion(phase_block)
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact contains traced command after "
            "completion sentinel"
        )
    if (
        phase_block is not None
        and _phase_block_has_nonempty_line_after_completion(phase_block)
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact contains non-empty output after "
            "completion sentinel"
        )
    if phase_block is not None and _phase_block_has_unparseable_command(phase_block):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact contains unparseable traced command"
        )
    if (
        phase_block is not None
        and _phase_block_has_unsupported_parenthesized_group(phase_block)
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact contains unsupported parenthesized traced command"
        )
    if (
        phase_block is not None
        and _phase_block_has_unexpected_runner_cd_wrapper(phase, phase_block)
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact contains unexpected runner cd wrapper directory"
        )
    if (
        phase == "dotnet-sdk"
        and phase_block is not None
        and _dotnet_phase_block_has_noncanonical_env_prefix(phase_block)
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact .NET phase used a non-canonical environment prefix"
        )
    if (
        phase == "dotnet-sdk"
        and phase_block is not None
        and _dotnet_phase_block_has_noncanonical_bridge_build_env_prefix(phase_block)
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact .NET native bridge build used a non-canonical environment prefix"
        )
    if (
        phase == "dotnet-sdk"
        and phase_block is not None
        and not _phase_block_has_ordered_command_fragments(
            phase,
            phase_block,
            (
                "dotnet --version",
                "dotnet --info",
                "cargo build -p connect_norito_bridge",
                "dotnet restore Hyperledger.Iroha.Sdk.sln",
                "dotnet test tests/Hyperledger.Iroha.Sdk.Tests/Hyperledger.Iroha.Sdk.Tests.csproj",
            ),
        )
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact .NET commands are not in required "
            "version-info-bridge-restore-test order"
        )
    if phase_block is not None:
        duplicate_phase_command = _phase_block_duplicate_command_fragment(
            phase,
            phase_block,
            PHASE_TRANSCRIPT_REQUIRED_FRAGMENTS.get(phase, ()),
        )
        if duplicate_phase_command is not None:
            duplicate_command_error = (
                ".NET command appears more than once:"
                if phase == "dotnet-sdk"
                else f"{PHASE_DUPLICATE_COMMAND_ERROR_FRAGMENT}:"
            )
            errors.append(
                "readiness report phase "
                f"{phase} evidence artifact {duplicate_command_error} "
                f"{_phase_diagnostic_fragment(duplicate_phase_command)}"
            )
    if (
        phase == "dotnet-sdk"
        and phase_block is not None
        and not _dotnet_phase_block_bridge_path_matches_target_dir(phase_block)
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact .NET native bridge path does not match "
            "CARGO_TARGET_DIR/debug handoff"
        )
    if (
        phase == "dotnet-sdk"
        and phase_block is not None
        and _dotnet_phase_block_forbidden_test_command(phase_block)
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact .NET phase ran a non-canonical dotnet test command"
        )
    if (
        phase == "dotnet-sdk"
        and phase_block is not None
        and _dotnet_phase_block_forbidden_setup_command(phase_block)
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact .NET phase ran a non-canonical dotnet setup command"
        )
    if (
        phase == "dotnet-sdk"
        and phase_block is not None
        and not _dotnet_phase_block_rid_architecture_markers_match(phase_block)
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact .NET RID and architecture markers disagree"
        )
    if (
        phase == "dotnet-sdk"
        and phase_block is not None
        and not _phase_block_output_fragments_are_strictly_ordered(
            phase_block,
            (
                DOTNET_BRIDGE_PATH_SUCCESS_PREFIX,
                DOTNET_BRIDGE_SHA256_SUCCESS_PREFIX,
            ),
        )
    ):
        errors.append(
            f"readiness report phase {phase} evidence artifact .NET native bridge markers are not in required path-sha256 order"
        )
    if (
        phase == "dotnet-sdk"
        and phase_block is not None
        and not _phase_block_output_fragments_are_strictly_ordered(
            phase_block,
            (
                DOTNET_TEST_PASSED_SUCCESS_FRAGMENT,
                DOTNET_TRX_SUCCESS_PREFIX,
                DOTNET_TRX_BYTES_SUCCESS_PREFIX,
            ),
        )
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact .NET success markers are not in "
            "required passed-trx-bytes order"
        )
    if phase == "dotnet-sdk" and phase_block is not None:
        duplicate_dotnet_marker = _phase_block_duplicate_output_fragment(
            phase_block,
            PHASE_TRANSCRIPT_SUCCESS_FRAGMENTS.get(phase, ()),
        )
        if duplicate_dotnet_marker is not None:
            errors.append(
                "readiness report phase "
                f"{phase} evidence artifact .NET evidence marker appears more "
                "than once: "
                f"{_phase_diagnostic_fragment(duplicate_dotnet_marker)}"
            )
    if (
        phase_block is not None
        and _transcript_has_multiple_known_phase_markers(transcript)
        and not _transcript_has_full_corridor_completion(transcript)
    ):
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact contains incomplete multi-phase "
            "corridor transcript"
        )
    required_fragments = PHASE_TRANSCRIPT_REQUIRED_FRAGMENTS.get(phase)
    if required_fragments is None:
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact has no expected command fragment configured"
        )
    elif phase_block is not None:
        for fragment in required_fragments:
            if not _phase_block_has_command_fragment(phase, phase_block, fragment):
                errors.append(
                    "readiness report phase "
                    f"{phase} evidence artifact is missing expected "
                    f"phase-block command: {_phase_diagnostic_fragment(fragment)}"
                )
    success_fragments = PHASE_TRANSCRIPT_SUCCESS_FRAGMENTS.get(phase)
    if success_fragments is None:
        errors.append(
            "readiness report phase "
            f"{phase} evidence artifact has no expected success fragment configured"
        )
    elif phase_block is not None:
        phase_command_positions = [
            position
            for fragment in PHASE_TRANSCRIPT_REQUIRED_FRAGMENTS.get(phase, ())
            for position in _phase_block_command_fragment_line_indices(
                phase,
                phase_block,
                fragment,
            )
        ]
        first_phase_command_position = (
            min(phase_command_positions) if phase_command_positions else -1
        )
        for fragment in success_fragments:
            if not _phase_block_has_output_fragment(phase, phase_block, fragment):
                errors.append(
                    "readiness report phase "
                    f"{phase} evidence artifact is missing expected "
                    "phase-block success marker: "
                    f"{_phase_diagnostic_fragment(fragment)}"
                )
            elif (
                not _phase_success_fragment_positions_are_only_in_required_command_windows(
                    phase,
                    phase_block,
                    fragment,
                    _phase_block_output_fragment_line_indices(phase_block, fragment),
                    first_phase_command_position,
                )
            ):
                outside_window_error = (
                    DOTNET_SUCCESS_OUTSIDE_WINDOW_ERROR_FRAGMENT
                    if phase == "dotnet-sdk"
                    else PHASE_SUCCESS_OUTSIDE_WINDOW_ERROR_FRAGMENT
                )
                errors.append(
                    "readiness report phase "
                    f"{phase} evidence artifact {outside_window_error}: "
                    f"{_phase_diagnostic_fragment(fragment)}"
                )
            elif phase != "dotnet-sdk":
                success_positions = _phase_block_output_fragment_line_indices(
                    phase_block,
                    fragment,
                )
                expected_windows = _phase_success_command_windows(
                    phase,
                    phase_block,
                    fragment,
                    first_phase_command_position,
                )
                if len(success_positions) > len(expected_windows):
                    errors.append(
                        "readiness report phase "
                        f"{phase} evidence artifact {PHASE_DUPLICATE_SUCCESS_ERROR_FRAGMENT}: "
                        f"{_phase_diagnostic_fragment(fragment)}"
                    )
    if phase_block is not None:
        forbidden_marker = _phase_block_forbidden_output_marker(phase, phase_block)
        if forbidden_marker is not None:
            errors.append(
                "readiness report phase "
                f"{phase} evidence artifact contains forbidden phase-block "
                f"failure marker: {_phase_diagnostic_fragment(forbidden_marker)}"
            )
    return errors


def _phase_transcript_artifact_path(
    bundle_dir: Path,
    artifact: Any,
) -> tuple[Path | None, list[str]]:
    if not isinstance(artifact, dict):
        return None, [
            "readiness report phase transcript cannot be checked: malformed artifact row"
        ]
    artifact_path = artifact.get("path")
    if not isinstance(artifact_path, str) or not artifact_path:
        return None, [
            "readiness report phase transcript cannot be checked: missing artifact path"
        ]
    canonical_path, path_errors = _canonical_artifact_path(artifact)
    if path_errors or canonical_path is None:
        return None, [
            "readiness report phase transcript cannot be checked: invalid artifact path"
        ]
    return bundle_dir.joinpath(*PurePosixPath(canonical_path).parts), []


def _sdk_test_inventory_errors(
    inventory: tuple[tuple[str | Path, tuple[str, ...]], ...],
    *,
    label: str,
) -> list[str]:
    """Return source-inventory errors for SDK test marker scans."""

    errors: list[str] = []
    for raw_path, markers in inventory:
        path = Path(raw_path)
        display_path = str(path)
        if not path.is_absolute():
            display_path = path.as_posix()
            path = ROOT / path
        try:
            source = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            errors.append(f"{label} SDK test inventory is not UTF-8 text")
            continue
        except OSError:
            errors.append(f"{label} SDK test inventory cannot be read")
            continue
        for marker in markers:
            if marker not in source:
                errors.append(
                    f"{label} SDK test inventory {display_path} missing "
                    f"marker: {marker}"
                )
    return errors


def _source_marker_inventory_errors(
    inventory: tuple[tuple[str | Path, tuple[str, ...]], ...],
    *,
    label: str,
) -> list[str]:
    """Return source-inventory errors for marker scans."""

    errors: list[str] = []
    for raw_path, markers in inventory:
        path = Path(raw_path)
        display_path = str(path)
        if not path.is_absolute():
            display_path = path.as_posix()
            path = ROOT / path
        try:
            source = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            errors.append(f"{label} source inventory is not UTF-8 text")
            continue
        except OSError:
            errors.append(f"{label} source inventory cannot be read")
            continue
        for marker in markers:
            if marker not in source:
                errors.append(
                    f"{label} source inventory {display_path} missing marker: {marker}"
                )
    return errors


def _source_inventory_relative_path(raw_path: str | Path) -> str:
    """Return a stable repository-relative inventory path when possible."""

    path = Path(raw_path)
    if path.is_absolute():
        try:
            return path.relative_to(ROOT).as_posix()
        except ValueError:
            return path.as_posix()
    return path.as_posix()


def _source_inventory_lane_coverage_errors(
    inventory: tuple[tuple[str | Path, tuple[str, ...]], ...],
    *,
    label: str,
    lane_markers: dict[str, tuple[tuple[str, str], ...]],
    expected_lanes: tuple[str, ...] | None = None,
) -> list[str]:
    """Return errors when source inventories drop active launch lanes."""

    errors: list[str] = []
    if expected_lanes is None:
        expected_lanes = tuple(
            ALL_LANES_CHAIN_BY_DOMAIN[domain]
            for domain in ALL_LANES_SUPPORTED_LAUNCH_DOMAINS
        )
    expected_lane_set = set(expected_lanes)
    missing_lane_entries = [lane for lane in expected_lanes if lane not in lane_markers]
    if missing_lane_entries:
        errors.append(
            f"{label} source inventory missing active launch lane coverage entries: "
            f"{', '.join(missing_lane_entries)}"
        )

    extra_lane_entries = [lane for lane in lane_markers if lane not in expected_lane_set]
    if extra_lane_entries:
        errors.append(
            f"{label} source inventory has non-launch lane coverage entries: "
            f"{', '.join(extra_lane_entries)}"
        )

    inventory_markers = {
        (_source_inventory_relative_path(raw_path), marker)
        for raw_path, markers in inventory
        for marker in markers
    }
    for lane in expected_lanes:
        missing_markers = [
            (path, marker)
            for path, marker in lane_markers.get(lane, ())
            if (path, marker) not in inventory_markers
        ]
        if missing_markers:
            rendered = "; ".join(
                f"{path} marker: {marker}" for path, marker in missing_markers
            )
            errors.append(
                f"{label} source inventory missing active launch lane coverage "
                f"for {lane}: {rendered}"
            )
    return errors


def _source_region(
    path: Path,
    *,
    start_marker: str,
    end_marker: str,
    label: str,
) -> tuple[str | None, list[str]]:
    """Return the source region delimited by two stable markers."""

    try:
        source = path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        return None, [f"{label} source is not UTF-8 text"]
    except OSError:
        return None, [f"{label} source cannot be read"]
    start = source.find(start_marker)
    if start == -1:
        return None, [f"{label} source {path.as_posix()} missing start marker: {start_marker}"]
    end = source.find(end_marker, start + len(start_marker))
    if end == -1:
        return None, [f"{label} source {path.as_posix()} missing end marker: {end_marker}"]
    return source[start:end], []


def _ethereum_data_collection_no_proxy_inventory_errors(
    regions: dict[str, tuple[str | Path, str, str, tuple[str, ...]]] | None = None,
    gate_inventory: tuple[tuple[str | Path, tuple[str, ...]], ...] | None = None,
) -> list[str]:
    """Return errors for Ethereum SDK data collection proxy-fallback guards."""

    if regions is None:
        regions = ETHEREUM_DATA_COLLECTION_REGIONS
    errors: list[str] = []
    for sdk, (raw_path, start_marker, end_marker, required_markers) in regions.items():
        path = Path(raw_path)
        display_path = path.as_posix()
        if not path.is_absolute():
            path = ROOT / path
        region, region_errors = _source_region(
            path,
            start_marker=start_marker,
            end_marker=end_marker,
            label=f"Ethereum mainnet {sdk} data collection",
        )
        errors.extend(region_errors)
        if region is None:
            continue
        for marker in required_markers:
            if marker not in region:
                errors.append(
                    "Ethereum mainnet "
                    f"{sdk} data collection source {display_path} missing "
                    f"provider marker: {marker}"
                )
        for label, pattern in ETHEREUM_DATA_COLLECTION_FORBIDDEN_PATTERNS.items():
            if pattern.search(region):
                errors.append(
                    "Ethereum mainnet "
                    f"{sdk} data collection source {display_path} contains "
                    f"forbidden {label}"
                )
    if gate_inventory is None:
        gate_inventory = ETHEREUM_DATA_COLLECTION_NO_PROXY_GATE_MARKERS
    errors.extend(
        _source_marker_inventory_errors(
            gate_inventory,
            label="Ethereum mainnet no-proxy data-collection gate",
        )
    )
    return errors


