def _source_adapter_gate_audit_key_blocker(key: Any) -> str | None:
    label = (
        "readiness report cryptographic evidence row "
        "source_adapter_gate_audit_hashes"
    )
    if not isinstance(key, str) or not key:
        return f"{label} contains an empty key"
    blocker = _native_evm_prover_field_name_blocker(label, key, "audit")
    if blocker == f"{label} contains audit field: {key}":
        return None
    if blocker == f"{label} contains audit field name with sensitive name":
        return None
    return blocker


def _source_adapter_gate_audit_keys_are_markdown_safe(value: Any) -> bool:
    if not isinstance(value, dict):
        return True
    return all(
        _source_adapter_gate_audit_key_blocker(audit_key) is None
        for audit_key in value
    )


