def _native_evm_prover_hash_role_blockers(payload: dict[str, Any]) -> list[str]:
    roles = [
        ("proof_artifact_hash", payload.get("proof_artifact_hash")),
        ("proving_key_hash", payload.get("proving_key_hash")),
        ("verifier_key_hash", payload.get("verifier_key_hash")),
        ("destination_binding_hash", payload.get("destination_binding_hash")),
    ]
    sdk_artifacts = payload.get("native_sdk_artifacts")
    if isinstance(sdk_artifacts, list):
        for index, artifact in enumerate(sdk_artifacts):
            if isinstance(artifact, dict):
                roles.append(
                    (
                        f"native_sdk_artifacts[{index}].implementation_hash",
                        artifact.get("implementation_hash"),
                    )
                )

    blockers: list[str] = []
    seen: dict[str, str] = {}
    for role, value in roles:
        if not _is_nonzero_hex32(value):
            continue
        previous_role = seen.get(value)
        if previous_role is not None:
            blockers.append(
                f"native EVM Groth16 prover bundle {role} must not reuse "
                f"{previous_role}"
            )
            continue
        seen[value] = role
    return blockers


def _native_evm_prover_fixture_hash_role_blockers(
    prefix: str,
    fixture: dict[str, Any],
    roles: tuple[str, ...],
) -> list[str]:
    blockers: list[str] = []
    seen: dict[str, str] = {}
    for role in roles:
        value = fixture.get(role)
        if not _is_nonzero_hex32(value):
            continue
        previous_role = seen.get(value)
        if previous_role is not None:
            blockers.append(f"{prefix} {role} must not reuse {previous_role}")
            continue
        seen[value] = role
    return blockers


def _native_evm_prover_payload_path_role_blockers(
    payload: dict[str, Any],
) -> list[str]:
    roles = [
        ("proof_artifact", payload.get("proof_artifact")),
        ("proving_key", payload.get("proving_key")),
        ("verifier_key", payload.get("verifier_key")),
        (
            "cross_sdk_fixture_parity_artifact",
            payload.get("cross_sdk_fixture_parity_artifact"),
        ),
        (
            "native_prover_self_test_artifact",
            payload.get("native_prover_self_test_artifact"),
        ),
    ]
    sdk_artifacts = payload.get("native_sdk_artifacts")
    if isinstance(sdk_artifacts, list):
        for index, artifact in enumerate(sdk_artifacts):
            if isinstance(artifact, dict):
                roles.append(
                    (
                        f"native_sdk_artifacts[{index}].implementation_artifact",
                        artifact.get("implementation_artifact"),
                    )
                )

    blockers: list[str] = []
    seen: dict[str, str] = {}
    for role, value in roles:
        relative_path, path_errors = _native_evm_manifest_relative_path(value, role)
        if path_errors or relative_path is None:
            continue
        path = relative_path.as_posix()
        previous_role = seen.get(path)
        if previous_role is not None:
            blockers.append(
                f"native EVM Groth16 prover bundle {role} path must not reuse "
                f"{previous_role}"
            )
            continue
        seen[path] = role
    return blockers


def _native_evm_prover_summary_path_role_errors(
    label: str,
    status: dict[str, Any],
) -> list[str]:
    roles = [
        ("artifact", status.get("artifact")),
        ("proof_artifact", status.get("proof_artifact")),
        ("proving_key", status.get("proving_key")),
        ("verifier_key", status.get("verifier_key")),
        (
            "cross_sdk_fixture_parity_artifact",
            status.get("cross_sdk_fixture_parity_artifact"),
        ),
        (
            "native_prover_self_test_artifact",
            status.get("native_prover_self_test_artifact"),
        ),
    ]
    sdk_artifacts = status.get("sdk_artifacts")
    if isinstance(sdk_artifacts, list):
        for index, row in enumerate(sdk_artifacts):
            if isinstance(row, dict):
                roles.append(
                    (
                        f"sdk_artifacts[{index}].implementation_artifact",
                        row.get("implementation_artifact"),
                    )
                )

    errors: list[str] = []
    seen: dict[str, str] = {}
    for role, artifact in roles:
        if not isinstance(artifact, dict):
            continue
        artifact_path, path_errors = _canonical_artifact_path(artifact)
        if path_errors or artifact_path is None:
            continue
        previous_role = seen.get(artifact_path)
        if previous_role is not None:
            errors.append(f"{label} {role} path must not reuse {previous_role}")
            continue
        seen[artifact_path] = role
    return errors


def _native_evm_prover_bundle_status_from_payload(
    artifact: dict[str, Any] | None,
    manifest_path: Path | None,
    payload: Any,
    evidence: dict[str, Any],
    blockers: list[str] | None = None,
) -> dict[str, Any]:
    blockers = list(blockers or [])
    if not isinstance(payload, dict):
        blockers.append("native EVM Groth16 prover bundle must be a JSON object")
        payload = {}

    for key in sorted(set(payload) - NATIVE_EVM_PROVER_BUNDLE_REQUIRED_KEYS):
        blockers.append(
            _native_evm_prover_field_name_blocker(
                "native EVM Groth16 prover bundle",
                key,
                "unknown",
            )
        )
    for key in sorted(NATIVE_EVM_PROVER_BUNDLE_REQUIRED_KEYS - set(payload)):
        blockers.append(f"native EVM Groth16 prover bundle missing field: {key}")

    expected_fields = {
        "schema": NATIVE_EVM_PROVER_BUNDLE_SCHEMA,
        "bundle_id": NATIVE_EVM_PROVER_BUNDLE_ID,
        "domain": ACTIVE_LAUNCH_DOMAIN,
        "chain": ACTIVE_LAUNCH_CHAIN,
        "proof_backend": "evm-groth16-bn254-v1",
        "browser_implementation": "pure-typescript",
    }
    for key, expected in expected_fields.items():
        if key in payload and payload.get(key) != expected:
            blockers.append(f"native EVM Groth16 prover bundle {key} must be {expected!r}")
    if payload.get("no_wasm") is not True:
        blockers.append("native EVM Groth16 prover bundle no_wasm must be true")
    if payload.get("remote_prover_required") is not False:
        blockers.append(
            "native EVM Groth16 prover bundle remote_prover_required must be false"
        )
    for key in (
        "proof_artifact_hash",
        "proving_key_hash",
        "verifier_key_hash",
        "destination_binding_hash",
    ):
        if key in payload and not _is_nonzero_hex32(payload.get(key)):
            blockers.append(
                f"native EVM Groth16 prover bundle {key} must be a canonical non-zero 32-byte hex value"
            )
    blockers.extend(_native_evm_prover_hash_role_blockers(payload))
    blockers.extend(_native_evm_prover_payload_path_role_blockers(payload))

    lane = _active_launch_lane(evidence) or {}
    destination_binding = lane.get("destination_binding")
    if not isinstance(destination_binding, dict):
        destination_binding = {}
    expected_destination_binding = destination_binding.get("destination_binding_hash")
    if (
        expected_destination_binding
        and payload.get("destination_binding_hash") != expected_destination_binding
    ):
        blockers.append(
            "native EVM Groth16 prover bundle destination_binding_hash must match "
            f"{ACTIVE_LAUNCH_DISPLAY} destination binding evidence"
        )

    audit_hashes = payload.get("audit_hashes")
    if not isinstance(audit_hashes, dict) or not audit_hashes:
        blockers.append(
            "native EVM Groth16 prover bundle audit_hashes must be a non-empty object"
        )
        audit_hashes = {}
    else:
        for key in sorted(set(audit_hashes) - set(NATIVE_EVM_PROVER_REQUIRED_AUDIT_HASHES)):
            blockers.append(
                _native_evm_prover_field_name_blocker(
                    "native EVM Groth16 prover bundle audit_hashes",
                    key,
                    "unexpected",
                )
            )
        for key in sorted(set(NATIVE_EVM_PROVER_REQUIRED_AUDIT_HASHES) - set(audit_hashes)):
            blockers.append(
                "native EVM Groth16 prover bundle "
                f"audit_hashes missing field: {key}"
            )
        semantic_audit_hashes = {
            key: audit_hashes[key]
            for key in NATIVE_EVM_PROVER_REQUIRED_AUDIT_HASHES
            if key in audit_hashes
        }
        reserved_audit_hash_roles = {
            "proof_artifact_hash": payload.get("proof_artifact_hash"),
            "proving_key_hash": payload.get("proving_key_hash"),
            "verifier_key_hash": payload.get("verifier_key_hash"),
            "destination_binding_hash": payload.get("destination_binding_hash"),
        }
        sdk_artifact_rows = payload.get("native_sdk_artifacts")
        if isinstance(sdk_artifact_rows, list):
            for sdk_index, sdk_artifact in enumerate(sdk_artifact_rows):
                if isinstance(sdk_artifact, dict):
                    reserved_audit_hash_roles[
                        f"native_sdk_artifacts[{sdk_index}].implementation_hash"
                    ] = sdk_artifact.get("implementation_hash")
        seen_audit_hashes: dict[str, str] = {}
        for key, audit_hash in sorted(semantic_audit_hashes.items()):
            if not _is_nonzero_hex32(audit_hash):
                blockers.append(
                    "native EVM Groth16 prover bundle "
                    f"audit_hashes.{key} must be a canonical non-zero 32-byte hex value"
                )
                continue
            previous_key = seen_audit_hashes.get(audit_hash)
            if previous_key is not None:
                blockers.append(
                    "native EVM Groth16 prover bundle "
                    f"audit_hashes.{key} must not duplicate "
                    f"audit_hashes.{previous_key}"
                )
            seen_audit_hashes[audit_hash] = key
            for role, role_hash in reserved_audit_hash_roles.items():
                if audit_hash == role_hash:
                    blockers.append(
                        "native EVM Groth16 prover bundle "
                        f"audit_hashes.{key} must not reuse {role}"
                    )

    proof_artifact, proof_artifact_blockers = _native_evm_prover_payload_artifact(
        manifest_path,
        artifact,
        payload,
        "proof_artifact",
        "proof_artifact_hash",
        "proof_artifact",
        NATIVE_EVM_PROVER_MIN_PROOF_ARTIFACT_BYTES,
    )
    blockers.extend(proof_artifact_blockers)
    proving_key, proving_key_blockers = _native_evm_prover_payload_artifact(
        manifest_path,
        artifact,
        payload,
        "proving_key",
        "proving_key_hash",
        "proving_key",
        NATIVE_EVM_PROVER_MIN_PROVING_KEY_BYTES,
    )
    blockers.extend(proving_key_blockers)
    verifier_key, verifier_key_blockers = _native_evm_prover_payload_artifact(
        manifest_path,
        artifact,
        payload,
        "verifier_key",
        "verifier_key_hash",
        "verifier_key",
        NATIVE_EVM_PROVER_MIN_VERIFIER_KEY_BYTES,
    )
    blockers.extend(verifier_key_blockers)

    sdk_artifacts, sdk_blockers = _native_evm_prover_bundle_artifact_summary(
        payload.get("native_sdk_artifacts"),
        payload.get("proof_artifact_hash"),
        payload.get("proving_key_hash"),
        manifest_path,
        artifact,
    )
    blockers.extend(sdk_blockers)
    parity_artifact, parity_blockers = _native_evm_prover_parity_fixture_status(
        manifest_path,
        artifact,
        payload,
    )
    blockers.extend(parity_blockers)
    self_test_artifact, self_test_blockers = _native_evm_prover_self_test_status(
        manifest_path,
        artifact,
        payload,
    )
    blockers.extend(self_test_blockers)

    return {
        "required": True,
        "schema": payload.get("schema", NATIVE_EVM_PROVER_BUNDLE_SCHEMA),
        "artifact": artifact,
        "bundle_id": payload.get("bundle_id", ""),
        "lanes": ACTIVE_LAUNCH_CHAIN,
        "proof_backend": payload.get("proof_backend", "evm-groth16-bn254-v1"),
        "proof_artifact": proof_artifact,
        "proof_artifact_hash": payload.get("proof_artifact_hash", ""),
        "proving_key": proving_key,
        "proving_key_hash": payload.get("proving_key_hash", ""),
        "verifier_key": verifier_key,
        "verifier_key_hash": payload.get("verifier_key_hash", ""),
        "destination_binding_hash": payload.get("destination_binding_hash", ""),
        "audit_hashes": dict(
            sorted(
                (
                    key,
                    audit_hashes[key],
                )
                for key in NATIVE_EVM_PROVER_REQUIRED_AUDIT_HASHES
                if key in audit_hashes
            )
        ),
        "cross_sdk_fixture_parity_artifact": parity_artifact,
        "native_prover_self_test_artifact": self_test_artifact,
        "sdk_artifacts": sdk_artifacts,
        "validation_status": "passed" if not blockers else "blocked",
        "validation_blockers": blockers,
    }


def _missing_native_evm_prover_bundle_status() -> dict[str, Any]:
    return _native_evm_prover_bundle_status_from_payload(
        None,
        None,
        {},
        {},
        ["native EVM Groth16 prover bundle manifest is required"],
    )


def _expected_native_evm_prover_bundle_status(
    bundle_dir: Path,
    report: dict[str, Any],
    evidence: dict[str, Any],
) -> dict[str, Any]:
    raw_status = report.get("native_evm_prover_bundle")
    if not isinstance(raw_status, dict):
        return _missing_native_evm_prover_bundle_status()
    artifact = raw_status.get("artifact")
    if not isinstance(artifact, dict):
        return _missing_native_evm_prover_bundle_status()
    artifact_path = _bundle_artifact_path(bundle_dir, artifact)
    if artifact_path is None:
        return _missing_native_evm_prover_bundle_status()
    blockers: list[str] = []
    try:
        payload = _load_json(artifact_path)
    except DuplicateJsonKeyError as exc:
        payload = {}
        blockers.append(
            _native_evm_prover_duplicate_json_key_blocker(
                "native EVM Groth16 prover bundle",
                exc.key,
            )
        )
    except UnicodeDecodeError:
        payload = {}
        blockers.append("native EVM Groth16 prover bundle is not UTF-8 text")
    except json.JSONDecodeError:
        payload = {}
        blockers.append("native EVM Groth16 prover bundle is not valid JSON")
    except OSError:
        payload = {}
        blockers.append("native EVM Groth16 prover bundle cannot be read")
    return _native_evm_prover_bundle_status_from_payload(
        artifact,
        artifact_path,
        payload,
        evidence,
        blockers,
    )


def _native_evm_prover_bundle_summary_schema_errors(status: dict[str, Any]) -> list[str]:
    label = "readiness report native_evm_prover_bundle"
    errors: list[str] = []
    for key in sorted(set(status) - NATIVE_EVM_PROVER_BUNDLE_SUMMARY_KEYS):
        errors.append(
            _native_evm_prover_field_name_blocker(label, key, "unknown")
        )
    for key in sorted(NATIVE_EVM_PROVER_BUNDLE_SUMMARY_KEYS - set(status)):
        errors.append(f"{label} missing field: {key}")
    if status.get("required") is not True:
        errors.append(f"{label} required must be true")
    for field in (
        "schema",
        "bundle_id",
        "lanes",
        "proof_backend",
        "proof_artifact_hash",
        "proving_key_hash",
        "verifier_key_hash",
        "destination_binding_hash",
    ):
        errors.extend(_non_empty_string_field_errors(label, status, field))
    if status.get("schema") != NATIVE_EVM_PROVER_BUNDLE_SCHEMA:
        errors.append(f"{label} schema must be {NATIVE_EVM_PROVER_BUNDLE_SCHEMA}")
    if status.get("bundle_id") != NATIVE_EVM_PROVER_BUNDLE_ID:
        errors.append(f"{label} bundle_id must be {NATIVE_EVM_PROVER_BUNDLE_ID}")
    if status.get("lanes") != ACTIVE_LAUNCH_CHAIN:
        errors.append(f"{label} lanes must be {ACTIVE_LAUNCH_CHAIN}")
    if status.get("proof_backend") != "evm-groth16-bn254-v1":
        errors.append(f"{label} proof_backend must be evm-groth16-bn254-v1")
    for field in (
        "proof_artifact_hash",
        "proving_key_hash",
        "verifier_key_hash",
        "destination_binding_hash",
    ):
        if field in status and not _is_nonzero_hex32(status.get(field)):
            errors.append(
                f"{label} {field} must be a canonical non-zero 32-byte hex value"
            )
    artifact = status.get("artifact")
    if not isinstance(artifact, dict):
        errors.append(f"{label} artifact must be an object")
    else:
        for key in sorted(set(artifact) - ARTIFACT_KEYS):
            errors.append(
                _native_evm_prover_field_name_blocker(
                    f"{label} artifact",
                    key,
                    "unknown",
                )
            )
        path_errors = _canonical_artifact_path(artifact)[1]
        errors.extend(f"{label} artifact {error}" for error in path_errors)
    for artifact_field, hash_field in (
        ("proof_artifact", "proof_artifact_hash"),
        ("proving_key", "proving_key_hash"),
        ("verifier_key", "verifier_key_hash"),
    ):
        artifact = status.get(artifact_field)
        if not isinstance(artifact, dict):
            errors.append(f"{label} {artifact_field} must be an object")
            continue
        for key in sorted(set(artifact) - ARTIFACT_KEYS):
            errors.append(
                _native_evm_prover_field_name_blocker(
                    f"{label} {artifact_field}",
                    key,
                    "unknown",
                )
            )
        path_errors = _canonical_artifact_path(artifact)[1]
        errors.extend(f"{label} {artifact_field} {error}" for error in path_errors)
        artifact_hash = artifact.get("sha256")
        expected_hash = status.get(hash_field)
        if (
            _is_canonical_sha256_text(artifact_hash)
            and isinstance(expected_hash, str)
            and f"0x{artifact_hash}" != expected_hash
        ):
            errors.append(f"{label} {artifact_field} sha256 must match {hash_field}")
    parity_artifact = status.get("cross_sdk_fixture_parity_artifact")
    if not isinstance(parity_artifact, dict):
        errors.append(f"{label} cross_sdk_fixture_parity_artifact must be an object")
    else:
        for key in sorted(set(parity_artifact) - ARTIFACT_KEYS):
            errors.append(
                _native_evm_prover_field_name_blocker(
                    f"{label} cross_sdk_fixture_parity_artifact",
                    key,
                    "unknown",
                )
            )
        path_errors = _canonical_artifact_path(parity_artifact)[1]
        errors.extend(
            f"{label} cross_sdk_fixture_parity_artifact {error}"
            for error in path_errors
        )
    self_test_artifact = status.get("native_prover_self_test_artifact")
    if not isinstance(self_test_artifact, dict):
        errors.append(f"{label} native_prover_self_test_artifact must be an object")
    else:
        for key in sorted(set(self_test_artifact) - ARTIFACT_KEYS):
            errors.append(
                _native_evm_prover_field_name_blocker(
                    f"{label} native_prover_self_test_artifact",
                    key,
                    "unknown",
                )
            )
        path_errors = _canonical_artifact_path(self_test_artifact)[1]
        errors.extend(
            f"{label} native_prover_self_test_artifact {error}"
            for error in path_errors
        )
    audit_hashes = status.get("audit_hashes")
    if not isinstance(audit_hashes, dict) or not audit_hashes:
        errors.append(f"{label} audit_hashes must be a non-empty object")
    else:
        for key in sorted(set(audit_hashes) - set(NATIVE_EVM_PROVER_REQUIRED_AUDIT_HASHES)):
            errors.append(
                _native_evm_prover_field_name_blocker(
                    f"{label} audit_hashes",
                    key,
                    "unexpected",
                )
            )
        for key in sorted(set(NATIVE_EVM_PROVER_REQUIRED_AUDIT_HASHES) - set(audit_hashes)):
            errors.append(f"{label} audit_hashes missing field: {key}")
        semantic_audit_hashes = {
            key: audit_hashes[key]
            for key in NATIVE_EVM_PROVER_REQUIRED_AUDIT_HASHES
            if key in audit_hashes
        }
        reserved_audit_hash_roles = {
            "proof_artifact_hash": status.get("proof_artifact_hash"),
            "proving_key_hash": status.get("proving_key_hash"),
            "verifier_key_hash": status.get("verifier_key_hash"),
            "destination_binding_hash": status.get("destination_binding_hash"),
        }
        for index, row in enumerate(status.get("sdk_artifacts", [])):
            if isinstance(row, dict):
                reserved_audit_hash_roles[
                    f"sdk_artifacts[{index}].implementation_hash"
                ] = row.get("implementation_hash")
        seen_audit_hashes: dict[str, str] = {}
        for key, value in sorted(semantic_audit_hashes.items()):
            if not _is_nonzero_hex32(value):
                errors.append(
                    f"{label} audit_hashes.{key} must be a canonical non-zero 32-byte hex value"
                )
                continue
            previous_key = seen_audit_hashes.get(value)
            if previous_key is not None:
                errors.append(
                    f"{label} audit_hashes.{key} must not duplicate "
                    f"audit_hashes.{previous_key}"
                )
            seen_audit_hashes[value] = key
            for role, role_hash in reserved_audit_hash_roles.items():
                if value == role_hash:
                    errors.append(f"{label} audit_hashes.{key} must not reuse {role}")
        if isinstance(parity_artifact, dict):
            artifact_hash = parity_artifact.get("sha256")
            parity_hash = semantic_audit_hashes.get("cross_sdk_fixture_parity")
            if (
                _is_canonical_sha256_text(artifact_hash)
                and isinstance(parity_hash, str)
                and f"0x{artifact_hash}" != parity_hash
            ):
                errors.append(
                    f"{label} cross_sdk_fixture_parity_artifact sha256 must match "
                    "audit_hashes.cross_sdk_fixture_parity"
                )
        if isinstance(self_test_artifact, dict):
            artifact_hash = self_test_artifact.get("sha256")
            self_test_hash = semantic_audit_hashes.get("native_prover_self_test")
            if (
                _is_canonical_sha256_text(artifact_hash)
                and isinstance(self_test_hash, str)
                and f"0x{artifact_hash}" != self_test_hash
            ):
                errors.append(
                    f"{label} native_prover_self_test_artifact sha256 must match "
                    "audit_hashes.native_prover_self_test"
                )
    sdk_artifacts = status.get("sdk_artifacts")
    if not isinstance(sdk_artifacts, list) or not sdk_artifacts:
        errors.append(f"{label} sdk_artifacts must be a non-empty list")
    else:
        seen_sdks: set[str] = set()
        semantic_sdk_order: list[str] = []
        for index, row in enumerate(sdk_artifacts):
            row_label = f"{label} sdk_artifacts[{index}]"
            if not isinstance(row, dict):
                errors.append(f"{row_label} must be an object")
                continue
            for key in sorted(set(row) - NATIVE_EVM_PROVER_SDK_ARTIFACT_SUMMARY_KEYS):
                errors.append(
                    _native_evm_prover_field_name_blocker(row_label, key, "unknown")
                )
            for key in sorted(NATIVE_EVM_PROVER_SDK_ARTIFACT_SUMMARY_KEYS - set(row)):
                errors.append(f"{row_label} missing field: {key}")
            sdk = row.get("sdk")
            sdk_key_blocker = _native_evm_prover_summary_sdk_artifact_key_blocker(
                row_label,
                sdk,
            )
            if sdk_key_blocker is not None:
                errors.append(sdk_key_blocker)
                continue
            semantic_sdk_order.append(sdk)
            if sdk in seen_sdks:
                errors.append(
                    _native_evm_sdk_name_blocker(
                        f"{label} sdk_artifacts",
                        sdk,
                        "duplicate",
                    )
                )
            seen_sdks.add(sdk)
            expected_implementation = NATIVE_EVM_PROVER_REQUIRED_IMPLEMENTATIONS.get(sdk)
            if expected_implementation is None:
                errors.append(
                    _native_evm_sdk_name_blocker(
                        f"{label} sdk_artifacts",
                        sdk,
                        "unknown",
                    )
                )
            elif row.get("implementation") != expected_implementation:
                errors.append(
                    f"{row_label} implementation must be {expected_implementation}"
                )
            if not _is_nonzero_hex32(row.get("implementation_hash")):
                errors.append(
                    f"{row_label} implementation_hash must be a canonical non-zero 32-byte hex value"
                )
            implementation_artifact = row.get("implementation_artifact")
            if not isinstance(implementation_artifact, dict):
                errors.append(f"{row_label} implementation_artifact must be an object")
            else:
                for key in sorted(set(implementation_artifact) - ARTIFACT_KEYS):
                    errors.append(
                        _native_evm_prover_field_name_blocker(
                            f"{row_label} implementation_artifact",
                            key,
                            "unknown",
                        )
                    )
                path_errors = _canonical_artifact_path(implementation_artifact)[1]
                errors.extend(
                    f"{row_label} implementation_artifact {error}"
                    for error in path_errors
                )
                artifact_hash = implementation_artifact.get("sha256")
                if (
                    _is_canonical_sha256_text(artifact_hash)
                    and isinstance(row.get("implementation_hash"), str)
                    and f"0x{artifact_hash}" != row.get("implementation_hash")
                ):
                    errors.append(
                        f"{row_label} implementation_artifact sha256 must match "
                        "implementation_hash"
                    )
        for sdk in sorted(set(NATIVE_EVM_PROVER_REQUIRED_IMPLEMENTATIONS) - seen_sdks):
            errors.append(f"{label} sdk_artifacts missing sdk: {sdk}")
        if semantic_sdk_order != sorted(NATIVE_EVM_PROVER_REQUIRED_IMPLEMENTATIONS):
            errors.append(f"{label} sdk_artifacts must match expected SDK order")
    errors.extend(_native_evm_prover_summary_path_role_errors(label, status))
    if status.get("validation_status") != "passed":
        errors.append(f"{label} validation_status must be passed")
    errors.extend(
        _string_list_field_errors(
            label,
            status,
            "validation_blockers",
            allow_empty=True,
        )
    )
    if "validation_blockers" in status:
        errors.extend(
            _native_evm_validation_blockers(
                status.get("validation_blockers"),
                f"{label} validation_blockers",
            )
        )
    if status.get("validation_blockers"):
        errors.append(f"{label} validation_blockers must be empty")
    return errors


def _active_launch_release_checklist(
    evidence: dict[str, Any],
    native_prover_bundle: dict[str, Any] | None = None,
) -> dict[str, Any]:
    lane = _active_launch_lane(evidence) or {}
    lane_label = f"domain {ACTIVE_LAUNCH_DOMAIN} ({ACTIVE_LAUNCH_CHAIN})"
    lane_blockers, lane_blocker_schema_errors = (
        _active_launch_lane_blockers_for_checklist(
            lane.get("blockers"),
            lane_label,
        )
    )
    record_labels = {
        "source_verifier_material": "source verifier material",
        "source_adapter_deployment": "source adapter deployment",
        "destination_rollout": "destination rollout",
        "route_allowlist": "route allowlist",
    }
    records_blockers = _active_launch_required_record_metadata_blockers(
        lane_label,
        lane,
        record_labels,
    )
    deployment_blockers = [
        f"{lane_label}: {blocker}"
        for blocker in lane_blockers
        if any(
            token in blocker
            for token in (
                "source adapter",
                "deployment",
                "destination",
                "binding",
                "verifier",
                "rollout",
            )
        )
    ]
    deployment_blockers.extend(lane_blocker_schema_errors)
    if lane:
        deployment_blockers.extend(
            _active_launch_evm_live_metadata_blockers(lane_label, lane)
        )
        deployment_blockers.extend(
            _active_launch_governed_deployment_metadata_blockers(lane_label, lane)
        )
    route_blockers = [
        f"{lane_label}: {blocker}"
        for blocker in lane_blockers
        if "route allowlist" in blocker
    ]
    route_blockers.extend(lane_blocker_schema_errors)
    if lane:
        route_blockers.extend(
            _active_launch_route_allowlist_binding_blockers(lane_label, lane)
        )
    canary_blockers = [
        f"{lane_label}: {blocker}"
        for blocker in lane_blockers
        if "route canary" in blocker
    ]
    canary_blockers.extend(lane_blocker_schema_errors)
    route_summary = lane.get("route_allowlist")
    if not isinstance(route_summary, dict):
        route_summary = {}
    canary = route_summary.get("route_canary")
    if not isinstance(canary, dict):
        canary = {}
    if canary.get("status") != "passed":
        canary_blockers.append(f"{lane_label}: route canary status is not passed")
    canary_blockers.extend(
        _active_launch_route_canary_metadata_blockers(
            lane_label,
            canary,
            _active_launch_route_canary_upstream_hash_roles(lane),
        )
    )
    if (
        "evidence_bound" in canary
        and type(canary.get("evidence_bound")) is not bool
    ):
        canary_blockers.append(
            f"{lane_label}: route canary evidence_bound must be boolean"
        )
    if canary.get("evidence_bound") is not True:
        canary_blockers.append(f"{lane_label}: route canary evidence is not bound")

    if native_prover_bundle is None:
        native_prover_bundle = _missing_native_evm_prover_bundle_status()
    native_prover_blockers = _native_evm_validation_blockers(
        native_prover_bundle.get("validation_blockers"),
        "native EVM prover validation_blockers",
    )
    launch_blockers = _active_launch_blockers(evidence)
    items = [
        {
            "id": "all_required_lane_records",
            "title": f"Active {ACTIVE_LAUNCH_DISPLAY} SCCP lane has the required source, deployment, destination, and route records",
            "ready": not records_blockers,
            "blockers": records_blockers,
        },
        {
            "id": "governed_deployment_evidence",
            "title": f"{ACTIVE_LAUNCH_DISPLAY} source-adapter deployment and destination rollout are governed and hash-bound",
            "ready": not deployment_blockers,
            "blockers": deployment_blockers,
        },
        {
            "id": "route_allowlist_binding",
            "title": f"{ACTIVE_LAUNCH_DISPLAY} route allowlist binds the governed source and destination evidence",
            "ready": not route_blockers,
            "blockers": route_blockers,
        },
        {
            "id": "live_route_canary_evidence",
            "title": f"{ACTIVE_LAUNCH_DISPLAY} post-deploy route canary evidence is live, passed, and bound to the route",
            "ready": not canary_blockers,
            "blockers": canary_blockers,
        },
        {
            "id": "native_evm_groth16_prover_bundle",
            "title": f"{ACTIVE_LAUNCH_DISPLAY} browser and native SDKs ship an audited no-WASM, no-remote EVM Groth16 prover bundle",
            "ready": not native_prover_blockers,
            "blockers": native_prover_blockers,
        },
        {
            "id": "no_unresolved_blockers",
            "title": f"No active {ACTIVE_LAUNCH_DISPLAY} launch blockers remain",
            "ready": not launch_blockers,
            "blockers": launch_blockers,
        },
    ]
    return {
        "ready": all(item["ready"] is True for item in items),
        "items": items,
    }


def _readiness_markdown_record_flags(records: Any) -> str:
    if not isinstance(records, dict):
        records = {}
    labels = {
        "source_verifier_material": "source",
        "source_adapter_deployment": "deploy",
        "destination_rollout": "dest",
        "route_allowlist": "route",
    }
    return ", ".join(
        f"{label}={'yes' if records.get(field) is True else 'no'}"
        for field, label in labels.items()
    )


def _readiness_markdown_lane_row_cells(
    lane: Any,
) -> tuple[str, str, str, str, Any]:
    if not isinstance(lane, dict):
        return "-", "-", "blocked", _readiness_markdown_record_flags({}), [
            "lane summary must be an object"
        ]

    domain = lane.get("domain")
    chain = lane.get("chain")
    domain_cell = str(domain) if type(domain) is int else "-"
    chain_cell = (
        f"`{chain}`"
        if type(domain) is int and chain == ALL_LANES_CHAIN_BY_DOMAIN.get(domain)
        else "-"
    )
    lane_status = "ready" if lane.get("production_ready") is True else "blocked"
    return (
        domain_cell,
        chain_cell,
        lane_status,
        _readiness_markdown_record_flags(lane.get("records")),
        lane.get("blockers"),
    )


def _readiness_markdown_hash_cell(value: Any) -> str:
    if _is_nonzero_hex32(value):
        return f"`{value}`"
    return "-"


def _readiness_markdown_text_cell(value: Any) -> str:
    if (
        isinstance(value, str)
        and _public_blocker_text_blocker(
            value,
            "readiness report Markdown",
            "cell",
        )
        is None
        and not any(character.isspace() for character in value)
    ):
        return f"`{value}`"
    return "`-`"


def _readiness_markdown_audit_hashes_cell(value: Any) -> str:
    if not isinstance(value, dict) or not value:
        return "-"
    rows: list[str] = []
    for key, audit_hash in sorted(value.items(), key=lambda item: str(item[0])):
        if (
            _source_adapter_gate_audit_key_blocker(key) is not None
            or not _is_nonzero_hex32(audit_hash)
        ):
            return "`<invalid source_adapter_gate_audit_hashes>`"
        rows.append(f"`{key}`: `{audit_hash}`")
    return "<br>".join(rows) if rows else "-"


def _readiness_markdown_integer_cell(value: Any) -> str:
    if type(value) is int:
        return f"`{value}`"
    return "-"


def _readiness_markdown_boolean_cell(value: Any) -> str:
    if type(value) is bool:
        return "`true`" if value else "`false`"
    return "-"


def _readiness_markdown_crypto_row_cells(row: Any) -> list[str]:
    if not isinstance(row, dict):
        row = {}
    domain = row.get("domain")
    chain = row.get("chain")
    domain_cell = str(domain) if type(domain) is int else "-"
    chain_cell = (
        f"`{chain}`"
        if type(domain) is int and chain == ALL_LANES_CHAIN_BY_DOMAIN.get(domain)
        else "-"
    )
    canary_source = row.get("route_canary_evidence_source")
    safe_canary_source = (
        canary_source
        if isinstance(canary_source, str)
        and _public_blocker_text_blocker(
            canary_source,
            "readiness report Markdown",
            "route_canary_evidence_source",
        )
        is None
        else "-"
    )
    if row.get("route_canary_evidence_bound") is not True:
        safe_canary_source = f"{safe_canary_source} (unbound)"
    source_gate = _readiness_markdown_hash_cell(row.get("source_adapter_gate_hash"))
    if row.get("source_adapter_gate_required") is False and source_gate == "-":
        source_gate = "not required"
    return [
        domain_cell,
        chain_cell,
        _readiness_markdown_text_cell(row.get("evm_source_rpc_chain_id")),
        _readiness_markdown_text_cell(row.get("evm_source_block_tag")),
        _readiness_markdown_text_cell(row.get("evm_destination_rpc_chain_id")),
        _readiness_markdown_text_cell(row.get("evm_destination_block_tag")),
        _readiness_markdown_hash_cell(row.get("source_verifier_material_hash")),
        _readiness_markdown_hash_cell(
            row.get("source_adapter_engine_deployment_hash")
        ),
        _readiness_markdown_hash_cell(row.get("destination_binding_hash")),
        source_gate,
        _readiness_markdown_audit_hashes_cell(
            row.get("source_adapter_gate_audit_hashes")
        ),
        _readiness_markdown_hash_cell(row.get("route_allowlist_hash")),
        _readiness_markdown_hash_cell(row.get("route_canary_evidence_hash")),
        f"`{safe_canary_source}`",
        _readiness_markdown_hash_cell(row.get("route_canary_transaction_hash")),
        _readiness_markdown_integer_cell(
            row.get("route_canary_receipt_block_number")
        ),
        _readiness_markdown_hash_cell(row.get("route_canary_receipt_block_hash")),
        _readiness_markdown_boolean_cell(
            row.get("route_canary_receipt_block_finalized")
        ),
        _readiness_markdown_hash_cell(row.get("route_canary_block_receipts_root")),
        _readiness_markdown_hash_cell(row.get("route_canary_message_id")),
        _readiness_markdown_integer_cell(row.get("route_canary_block_number")),
        _readiness_markdown_integer_cell(row.get("route_canary_block_timestamp")),
    ]


def _readiness_markdown_sdk_helper_sets_cell(surface: Any) -> str:
    if not isinstance(surface, dict):
        return "`<invalid sdk_helper_symbols_by_sdk>`"
    lanes = surface.get("lanes")
    expected_helpers_by_sdk = (
        USER_PROVER_REQUIRED_HELPERS_BY_LANE_SDK.get(lanes)
        if isinstance(lanes, str)
        else None
    )
    if expected_helpers_by_sdk is None:
        return "`<invalid sdk_helper_symbols_by_sdk>`"
    helper_sets = surface.get("sdk_helper_symbols_by_sdk")
    if not isinstance(helper_sets, dict):
        return "`<invalid sdk_helper_symbols_by_sdk>`"
    if set(helper_sets) != set(expected_helpers_by_sdk):
        return "`<invalid sdk_helper_symbols_by_sdk>`"
    rows: list[str] = []
    sdk_order = tuple(
        sdk
        for sdk in (*USER_PROVER_SDK_PHASES, "dotnet-sdk")
        if sdk in expected_helpers_by_sdk
    ) or USER_PROVER_SDK_PHASES
    for sdk in sdk_order:
        helpers = helper_sets.get(sdk)
        expected_helpers = expected_helpers_by_sdk[sdk]
        if not isinstance(helpers, list) or tuple(helpers) != expected_helpers:
            return "`<invalid sdk_helper_symbols_by_sdk>`"
        if any(
            _submission_surface_helper_symbol_blocker(
                helper,
                "readiness report user prover submission surface row "
                f"sdk_helper_symbols_by_sdk[{sdk}]",
            )
            is not None
            for helper in helpers
        ):
            return "`<invalid sdk_helper_symbols_by_sdk>`"
        helper_text = ", ".join(f"`{helper}`" for helper in helpers)
        rows.append(f"`{sdk}`: {helper_text}")
    return "<br>".join(rows) if rows else "`<invalid sdk_helper_symbols_by_sdk>`"


def _readiness_markdown_string_list_cell(value: Any, *, field_label: str) -> str:
    if not isinstance(value, list):
        return f"`<invalid {field_label}>`"
    if not value:
        return "-"
    if not all(isinstance(item, str) and item for item in value):
        return f"`<invalid {field_label}>`"
    if any(
        _public_blocker_text_blocker(item, "readiness report Markdown", field_label)
        is not None
        for item in value
    ):
        return f"`<invalid {field_label}>`"
    return "<br>".join(value)


def _readiness_user_prover_validation_blockers_cell(value: Any) -> str:
    field_label = "validation_blockers"
    if not isinstance(value, list):
        return f"`<invalid {field_label}>`"
    if not value:
        return "-"
    if not all(isinstance(item, str) and item for item in value):
        return f"`<invalid {field_label}>`"
    for item in value:
        if _path_control_character(item) is not None:
            return f"`<invalid {field_label}>`"
        if not item.isascii() or item.strip() != item:
            return f"`<invalid {field_label}>`"
        if _path_markdown_unsafe_character(item) is not None:
            return f"`<invalid {field_label}>`"
        if any(marker in item.lower() for marker in SENSITIVE_PUBLIC_FIELD_NAME_MARKERS):
            return f"`<invalid {field_label}>`"
    return "<br>".join(value)


def _readiness_markdown_user_prover_code_cell(
    value: Any,
    *,
    field_label: str,
    expected: str | None,
) -> str:
    if (
        isinstance(value, str)
        and expected is not None
        and value == expected
        and _public_blocker_text_blocker(value, "readiness report Markdown", field_label)
        is None
        and not any(character.isspace() for character in value)
    ):
        return f"`{value}`"
    return f"`<invalid {field_label}>`"


def _readiness_markdown_user_prover_text_cell(
    value: Any,
    *,
    field_label: str,
    expected: str | None,
) -> str:
    if (
        isinstance(value, str)
        and expected is not None
        and value == expected
        and _public_blocker_text_blocker(value, "readiness report Markdown", field_label)
        is None
    ):
        return value
    return f"`<invalid {field_label}>`"


def _readiness_markdown_user_prover_required_phases_cell(
    surface: dict[str, Any],
) -> str:
    lanes = surface.get("lanes")
    proof_backend = surface.get("proof_backend")
    expected_phases = (
        tuple(_expected_submission_surface_required_phases(lanes, proof_backend))
        if isinstance(lanes, str) and isinstance(proof_backend, str)
        else None
    )
    required_phases = surface.get("required_phases")
    if (
        expected_phases is not None
        and isinstance(required_phases, list)
        and tuple(required_phases) == expected_phases
        and all(
            isinstance(phase, str)
            and _submission_surface_required_phase_blocker(phase) is None
            for phase in required_phases
        )
    ):
        return ", ".join(f"`{phase}`" for phase in required_phases)
    return "`<invalid required_phases>`"


def _readiness_markdown_user_prover_validation_cell(
    surface: dict[str, Any],
) -> str:
    validation_status = surface.get("validation_status")
    validation = validation_status if validation_status in {"passed", "blocked"} else "blocked"
    validation_issues: list[str] = []
    if validation_status not in {"passed", "blocked"}:
        validation_issues.append("`<invalid validation_status>`")
    validation_blockers = surface.get("validation_blockers")
    if not isinstance(validation_blockers, list) or validation_blockers:
        validation_issues.append(
            _readiness_user_prover_validation_blockers_cell(validation_blockers)
        )
    if validation_issues:
        validation += ": " + "<br>".join(validation_issues)
    return validation


def _readiness_markdown_user_prover_surface_row_cells(surface: Any) -> list[str]:
    if not isinstance(surface, dict):
        return [
            "`<invalid lanes>`",
            "`<invalid proof_backend>`",
            "`<invalid sdk_helper_symbols_by_sdk>`",
            "`<invalid on_chain_submission>`",
            "`<invalid required_phases>`",
            "blocked: submission surface must be an object",
        ]
    lanes = surface.get("lanes")
    expected_backend = (
        USER_PROVER_REQUIRED_LANE_BACKENDS.get(lanes)
        if isinstance(lanes, str)
        else None
    )
    expected_submission = (
        USER_PROVER_ON_CHAIN_SUBMISSION_BY_LANE.get(lanes)
        if isinstance(lanes, str)
        else None
    )
    return [
        _readiness_markdown_user_prover_code_cell(
            lanes,
            field_label="lanes",
            expected=(
                lanes
                if isinstance(lanes, str)
                and lanes in USER_PROVER_REQUIRED_LANE_BACKENDS
                else None
            ),
        ),
        _readiness_markdown_user_prover_code_cell(
            surface.get("proof_backend"),
            field_label="proof_backend",
            expected=expected_backend,
        ),
        _readiness_markdown_sdk_helper_sets_cell(surface),
        _readiness_markdown_user_prover_text_cell(
            surface.get("on_chain_submission"),
            field_label="on_chain_submission",
            expected=expected_submission,
        ),
        _readiness_markdown_user_prover_required_phases_cell(surface),
        _readiness_markdown_user_prover_validation_cell(surface),
    ]


def _readiness_native_evm_validation_blockers_cell(value: Any) -> str:
    field_label = "validation_blockers"
    if not isinstance(value, list):
        return f"`<invalid {field_label}>`"
    if not value:
        return "-"
    for index, item in enumerate(value):
        if (
            _native_evm_validation_blocker_issue(
                item,
                "native EVM prover validation_blockers",
                index,
            )
            is not None
        ):
            return f"`<invalid {field_label}>`"
    return "<br>".join(value)


def _readiness_native_evm_markdown_path_is_safe(value: Any) -> bool:
    return (
        isinstance(value, str)
        and bool(value)
        and value.strip() == value
        and value.isascii()
        and _path_control_character(value) is None
        and _path_markdown_unsafe_character(value) is None
        and _path_percent_encoded_traversal(value) is None
        and not any(
            marker in value.lower()
            for marker in SENSITIVE_PUBLIC_FIELD_NAME_MARKERS
        )
    )


def _readiness_native_evm_markdown_text_is_safe(value: Any) -> bool:
    return (
        isinstance(value, str)
        and _public_blocker_text_blocker(value, "readiness report Markdown", "cell")
        is None
        and not any(character.isspace() for character in value)
    )


def _readiness_native_evm_artifact_path_cell(
    artifact: Any,
    *,
    field_label: str,
) -> str:
    if not isinstance(artifact, dict):
        return "-"
    artifact_path = artifact.get("path")
    if _readiness_native_evm_markdown_path_is_safe(artifact_path):
        return f"`{artifact_path}`"
    return f"`<invalid {field_label}>`"


def _readiness_native_evm_artifact_hash_cell(
    artifact: Any,
    *,
    field_label: str,
) -> str:
    if not isinstance(artifact, dict):
        return "-"
    artifact_hash = artifact.get("sha256")
    if _is_canonical_sha256_text(artifact_hash):
        return f"`{artifact_hash}`"
    return f"`<invalid {field_label}.sha256>`"


def _readiness_native_evm_hex32_cell(value: Any, *, field_label: str) -> str:
    if value is None:
        return "-"
    if _is_nonzero_hex32(value):
        return f"`{value}`"
    return f"`<invalid {field_label}>`"


def _readiness_native_evm_support_artifact_cell(
    artifact: Any,
    *,
    field_label: str,
) -> str:
    if not isinstance(artifact, dict):
        return "-"
    artifact_path = artifact.get("path")
    artifact_hash = artifact.get("sha256")
    if (
        _readiness_native_evm_markdown_path_is_safe(artifact_path)
        and _is_canonical_sha256_text(artifact_hash)
    ):
        return f"`{artifact_path}`<br>`{artifact_hash}`"
    return f"`<invalid {field_label}>`"


def _readiness_native_evm_sdk_artifacts_cell(value: Any) -> str:
    if not isinstance(value, list) or not value:
        return "-"
    by_sdk: dict[str, dict[str, Any]] = {}
    for row in value:
        if not isinstance(row, dict):
            return "`<invalid sdk_artifacts>`"
        sdk = row.get("sdk")
        if (
            not isinstance(sdk, str)
            or sdk in by_sdk
            or sdk not in NATIVE_EVM_PROVER_REQUIRED_IMPLEMENTATIONS
        ):
            return "`<invalid sdk_artifacts>`"
        by_sdk[sdk] = row
    if set(by_sdk) != set(NATIVE_EVM_PROVER_REQUIRED_IMPLEMENTATIONS):
        return "`<invalid sdk_artifacts>`"
    rows = [
        "`{sdk}`: `{implementation}` {implementation_hash}".format(
            sdk=sdk,
            implementation=row.get("implementation"),
            implementation_hash=(
                f"`{row.get('implementation_hash')}`"
                if _is_nonzero_hex32(row.get("implementation_hash"))
                else "`<invalid implementation_hash>`"
            ),
        )
        for sdk, row in sorted(by_sdk.items())
        if row.get("implementation") == NATIVE_EVM_PROVER_REQUIRED_IMPLEMENTATIONS[sdk]
        and _readiness_native_evm_markdown_text_is_safe(sdk)
        and _readiness_native_evm_markdown_text_is_safe(row.get("implementation"))
    ]
    if len(rows) != len(NATIVE_EVM_PROVER_REQUIRED_IMPLEMENTATIONS):
        return "`<invalid sdk_artifacts>`"
    if any("`<invalid implementation_hash>`" in row for row in rows):
        return "`<invalid sdk_artifacts>`"
    return "<br>".join(rows)


def _readiness_native_evm_bundle_status_cell(native_bundle: dict[str, Any]) -> str:
    status = native_bundle.get("validation_status")
    return status if status in {"passed", "blocked"} else "blocked"


def _readiness_native_evm_bundle_blockers_cell(native_bundle: dict[str, Any]) -> str:
    blockers = _readiness_native_evm_validation_blockers_cell(
        native_bundle.get("validation_blockers")
    )
    if native_bundle.get("validation_status") in {"passed", "blocked"}:
        return blockers
    invalid_status = "`<invalid validation_status>`"
    if blockers == "-":
        return invalid_status
    return invalid_status + "<br>" + blockers


